<?php

declare(strict_types=1);

namespace App\Models;

use App\Support\Ids\HasPrefixedId;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Database\Eloquent\Relations\MorphMany;
use Illuminate\Support\Carbon;

/* @properties-start (generated by dev:model-docs) */
/**
 * @property string $id
 * @property string $conversation_id
 * @property string|null $sender_id
 * @property string $kind
 * @property string $body
 * @property array|null $flags
 * @property array|null $context
 * @property Carbon|null $read_at
 * @property Carbon|null $created_at
 * @property Carbon|null $updated_at
 */
/* @properties-end */
class Message extends Model
{
    use HasPrefixedId;

    protected static string $idPrefix = 'msg';

    protected $fillable = ['conversation_id', 'sender_id', 'kind', 'body', 'flags', 'context', 'read_at'];

    protected function casts(): array
    {
        return [
            'flags' => 'array',
            'context' => 'array',
            'read_at' => 'datetime',
        ];
    }

    /** @return BelongsTo<Conversation, $this> */
    public function conversation(): BelongsTo
    {
        return $this->belongsTo(Conversation::class);
    }

    /** @return BelongsTo<User, $this> */
    public function sender(): BelongsTo
    {
        return $this->belongsTo(User::class, 'sender_id');
    }

    /** @return MorphMany<Media, $this> */
    public function attachments(): MorphMany
    {
        return $this->morphMany(Media::class, 'attachable')->where('collection', 'attachments')->orderBy('position');
    }
}
